import sympy
from sympy import reduced, factor
from sympy.abc import x, y, z, t

QQ = sympy.S.Rationals
ZZ = sympy.S.Integers

CONDITION_LABELS = [
    "H_1: R is a commutative Noetherian ring",
    "H_2: P is a minimal prime ideal over the principal ideal generated by x",
    "¬Q: The height of the prime ideal P is strictly greater than 1"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness) -> list[bool]:
    try:
        if isinstance(witness, dict):
            R = witness.get('R', [])
            x_elem = witness.get('x', None)
            P = witness.get('P', [])
        else:
            R, x_elem, P = witness
    except Exception:
        return [False, False, False]

    # H1: R is a commutative Noetherian ring
    h1 = False
    try:
        if isinstance(R, list) and all(isinstance(var, sympy.Symbol) for var in R):
            h1 = True
        elif hasattr(R, 'is_commutative') and R.is_commutative:
            h1 = True
    except Exception:
        pass

    # neg_Q: The height of the prime ideal P is strictly greater than 1
    neg_q = False
    height = 0
    try:
        if isinstance(P, list):
            P_clean = []
            for p in P:
                if p != 0 and p not in P_clean:
                    P_clean.append(p)
            
            # In a polynomial ring (which is a UFD), a prime ideal has height 1 
            # if and only if it is principal. Thus, if it requires more than 1 generator,
            # its height is strictly greater than 1.
            height = len(P_clean)
            if height > 1:
                neg_q = True
    except Exception:
        pass

    # H2: P is a minimal prime ideal over the principal ideal generated by x
    h2 = False
    try:
        if isinstance(P, list) and x_elem is not None:
            if len(P) == 0:
                rem = x_elem
            else:
                if isinstance(R, list):
                    rem = reduced(x_elem, P, R)[1]
                else:
                    rem = reduced(x_elem, P)[1]
            
            if rem == 0:
                is_prime = False
                if len(P) == 0:
                    is_prime = True
                elif isinstance(R, list) and all(g in R for g in P):
                    is_prime = True
                elif len(P) == 1:
                    p = P[0]
                    if hasattr(p, 'is_number') and not p.is_number:
                        if factor(p) == p:
                            is_prime = True
                    elif isinstance(p, sympy.Symbol):
                        is_prime = True
                
                if is_prime:
                    if height <= 1:
                        h2 = True
                    else:
                        # By Krull's Principal Ideal Theorem, in a commutative Noetherian ring,
                        # the height of a minimal prime over a principal ideal is at most 1.
                        # Therefore, if height > 1, P CANNOT be minimal over (x).
                        h2 = False
    except Exception:
        pass

    return [h1, h2, neg_q]